import numpy as np
def solve(g):
    g=np.array(g); H,W=g.shape; out=g.copy()
    blocks=[]
    for r in range(H-2):
        for c in range(W-2):
            v=g[r,c]
            if v!=0 and (g[r:r+3,c:c+3]==v).all():
                blocks.append((v,r+1,c+1))
    claim={}
    for v,cr,cc in blocks:
        for c in range(W): claim[(cr,c)]=v
        for r in range(H): claim[(r,cc)]=v
    for (r,c),v in claim.items():
        out[r,c]=v
    # conflicts: cells claimed by two different colors -> 0
    from collections import defaultdict
    cl=defaultdict(set)
    for v,cr,cc in blocks:
        for c in range(W): cl[(cr,c)].add(v)
        for r in range(H): cl[(r,cc)].add(v)
    for k,vs in cl.items():
        if len(vs)>1: out[k]=0
    return out

